// Converte a string MQTT em objeto
const raw = $input.first().json.message;
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  throw new Error('Payload MQTT inválido (não é JSON): ' + raw);
}

// Validação de campos obrigatórios
const obrigatorios = ['device_id', 'fumaca', 'presenca_notificavel', 'distancia'];
for (const campo of obrigatorios) {
  if (payload[campo] === undefined) {
    throw new Error('Campo obrigatório ausente: ' + campo);
  }
}

// Sanitização: garante que valores numéricos são de fato números
// Protege o Execute Command de command injection
const sanitizado = {
  device_id:            String(payload.device_id).replace(/[^a-zA-Z0-9_-]/g, ''),
  temp:                 payload.temp    !== null ? parseFloat(payload.temp)    : null,
  umid:                 payload.umid    !== null ? parseFloat(payload.umid)    : null,
  fumaca:               parseInt(payload.fumaca,               10),
  presenca_notificavel: parseInt(payload.presenca_notificavel, 10),
  distancia:            parseFloat(payload.distancia),
};

// Rejeita NaN (sensor defeituoso ou payload malformado)
if (isNaN(sanitizado.fumaca) || isNaN(sanitizado.presenca_notificavel) || isNaN(sanitizado.distancia)) {
  throw new Error('Valores numéricos inválidos no payload: ' + JSON.stringify(payload));
}

return [{ json: sanitizado }];

const { execSync } = require('child_process');

// process não existe no sandbox do n8n — lemos via printenv
const getEnv = (name) => {
  try { return execSync(`printenv ${name}`).toString().trim(); }
  catch { return null; }
};

const server = getEnv('ZABBIX_SERVER');
const host   = getEnv('ZABBIX_HOST_NAME');

if (!server || !host) return [$input.first()]; // sem config → pula silenciosamente

const d = $input.first().json;

const send = (key, value) => {
  if (value === null || value === undefined) return;
  execSync(`zabbix_sender -z "${server}" -s "${host}" -k ${key} -o "${value}"`);
};

try {
  send('temperatura', d.temp);
  send('umidade',     d.umid);
  send('fumaca',      d.fumaca);
  send('presenca',    d.presenca_notificavel);
} catch (e) {
  // Falha no Zabbix não bloqueia o fluxo (continueOnFail)
}

return [$input.first()];
